fix_code:
public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	int N = sc.nextInt();
	int M = sc.nextInt();

	long[] A = new long[N];
	long[] B = new long[M];

	for(int i = 0; i < N; i++) {
		A[i] = sc.nextInt();
	}
	for(int i = 0; i < M; i++) {
		B[i] = sc.nextInt();
	}

	Arrays.sort(A);
	Arrays.sort(B);

	long totalPayment = 0;
	boolean isSucceed = true;

	int j = 0;
	for (int i = 0; i < M; i++) {
		while (j < N && A[j] < B[i]) {
			j++;
		}
		if (j == N) {
			isSucceed = false;
			break;
		}
		totalPayment += A[j];
		j++;
	}

	if(isSucceed) {
		System.out.println(totalPayment);
	} else { 
		System.out.println(-1);
	}
}

